quests[8689] = { title = "Shroud of Infinite Wisdom", description = "I'm glad to hear you're aiding us in our attack on Ahn'Qiraj, $N.  I can make you a protective item that'll be of assistance in the fight against our enemy, $c.\n\nI shall need a Qiraji drape, which I'll resize for you of course.  I'll also need idols and scarabs which I'll use to create a suitable clasp.\n\nI promise you won't be disappointed.", objectives = "Bring 1 Qiraji Martial Drape, 2 Jasper Idols, 5 Gold Scarabs and 5 Clay Scarabs to Keyl Swiftclaw in Silithus.  You must also obtain Revered reputation with Cenarion Circle to complete this quest.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
