quests[8728] = { title = "The Good News and The Bad News", description = "Well that took a little longer than expected. Now let me see what this ledger says.\n\n<Narain silently reads the ledger, periodically mumbling under his breath.>\n\n The good news is that I am 99% certain that I am capable of creating an arcanite buoy that will function to your specifications. This is, of course, wholly dependant on the bad news.\n\nThe bad news is that I'm going to need a lot of arcanite, elementium ore, and rare gemstones.\n\nBring me what I need and I will craft the buoy.", objectives = "Narain Soothfancy in Tanaris wants you to bring him 20 Arcanite Bars, 10 Elementium Ore, 10 Azerothian Diamonds, and 10 Blue Sapphires.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8729] = { title = "The Wrath of Neptulon", description = "Did I mention the bad news yet? Its name is Maws: 100 feet of death and destruction. I guess I may have forgotten that little tidbit.\n\nAccording to my superior psycho-psionic clairvoyance, you'll find that the best spot to cast this buoy is off the coast of Azshara, in the Bay of Storms.\n\nLook for a swirling maelstrom, most likely cluttered with wreckage.\n\nBy the by, I hope you have friends.\n\nNow if you somehow miraculously succeed, take the scepter shard to Anachronos.", objectives = "Use the Arcanite Buoy at the Swirling Maelstrom at the Bay of Storms in Azshara.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8730] = { title = "Nefarius's Corruption", description = "Champion, is it you? A thousand years it has been since I was entrusted the shard and it is at my darkest hour that one should rise to relieve me of it... But what would tragedy be without cruelty?\n\n<Vaelastrasz coughs weakly.>\n\nNe... Nefarius now holds the scepter shard.\n\nTime is of the essence. Nefarius plans to destroy the shard. You must hurry!", objectives = "Slay Nefarian and recover the Red Scepter Shard. Return the Red Scepter Shard to Anachronos at the Caverns of Time in Tanaris. You have 5 hours to complete this task.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8731] = { title = "Field Duty", description = "Greetings, $N.  Before I assign you to more involved tasks in the war, you'll need to do your share of field duty.  \n\nYou will find Captain Skullsplit's Orgrimmar Legion outside Hive'Regal.\n\nReport to him and come back to me with proof of your field service.  I shall have a more advanced assignment ready for you.\n\nOh, please do your best to stay away from the Ironforge Brigade.  Tensions are high among our Alliance and Horde volunteers.", objectives = "Report to Krug Skullsplit at the Orgrimmar Legion post in front of Hive'Regal.  Prepare your Unsigned Field Duty Papers, obtain Signed Field Duty Papers and bring them to Windcaller Kaldon in Cenarion Hold.\n\nNote: Healing or casting beneficial spells on a member of the Orgrimmar Legion will flag you for PvP.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8732] = { title = "Field Duty Papers", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8733] = { title = "Eranikus, Tyrant of the Dream", description = "This is a journey of redemption, hero. Would it be that I was slain today, I would have died for a just and righteous cause. You must recover the green scepter shard. You must cleanse Eranikus of the taint placed upon him by the Old Gods.\n\nTravel to Darnassus. Just outside the city walls you will find one of my agents. This agent will set things in motion for us and inform Tyrande of our plans without alerting Staghelm.\n\n<Malfurion sighs.>\n\nA fall from grace a thousand years in the making...", objectives = "Travel to the continent of Teldrassil and find Malfurion's agent somewhere outside the walls of Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8734] = { title = "Tyrande and Remulos", description = "Tyrande will be notifed, mortal. Shan'do Stormrage has prepared me for this contingency.\n\nNow you must venture to the Moonglade and speak with Remulos. He will have further instruction as to the summoning of Eranikus.\n\nWe all wish you great luck.", objectives = "Travel to the Moonglade and speak to Keeper Remulos. ", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
